import React from 'react'
import { Link } from 'react-router-dom'

const Pricing = (props) => {
    const ClickHandler = () => {
        window.scrollTo(10, 0);
    }


    const pricing = [
        {
            fIcon: 'fi flaticon-medal',
            li1: '24/7 Support available',
            li2: 'eb Design @ Development',
            li3: '30-Day analytics & insights',
            li4: 'Ultimate Features',
            title: 'Basic Pack',
            link: '/pricing',
            price:'320',
        },
        {
            fIcon: 'fi flaticon-stats',
            li1: '24/7 Support available',
            li2: 'eb Design @ Development',
            li3: '30-Day analytics & insights',
            li4: 'Ultimate Features',
            title: 'Standard Pack',
            link: '/pricing',
            price:'400',
        },
        {
            fIcon: 'fi flaticon-trophy',
            li1: '24/7 Support available',
            li2: 'eb Design @ Development',
            li3: '30-Day analytics & insights',
            li4: 'Ultimate Features',
            title: 'Extended Pack',
            link: '/pricing',
            price:'650',
        },


    ]


    return (
        <>
        <style>{`
            .pricing-item {
                border: 2px solid #fff !important;
                background-color: rgba(255, 255, 255, 0.05) !important;
                padding: 40px !important;
                border-radius: 10px !important;
            }
            .pricing-item h2,
            .pricing-item h3,
            .pricing-item li,
            .pricing-item span {
                color: #fff !important;
            }
            .price-price h3,
            .price-price span {
                color: #fff !important;
            }
        `}</style>
        <section className="pricing-section section-padding" style={{color: '#fff'}}>
            <div className="container">
                <div className="pricing-items">
                    <div className="row">
                        {pricing.map((pricing, ptem) => (
                            <div className="col col-lg-4 col-md-6 col-12" key={ptem}>
                                <div className="pricing-item">
                                    <h2>{pricing.title}</h2>
                                    <div className="price-price">
                                        <h3>${pricing.price}<span>/Monthly</span></h3>
                                    </div>
                                    <ul>
                                        <li>{pricing.li1}</li>
                                        <li>{pricing.li2}</li>
                                        <li>{pricing.li3}</li>
                                        <li>{pricing.li4}</li>
                                    </ul>
                                    <Link className="btn-style-2" onClick={ClickHandler} to={pricing.link} style={{color: '#fff'}}>Choose Plan</Link>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            </div>
        </section>
        </>
    )
}

export default Pricing;
